// src/pages/AdminDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

const Card = ({ title, children }) => (
  <div className="bg-white p-5 rounded-xl shadow mb-5">
    <h2 className="text-blue-600 mb-4 text-xl font-semibold">{title}</h2>
    {children}
  </div>
);

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});
  const [message, setMessage] = useState("");
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const [selectedElectionVotingOpen, setSelectedElectionVotingOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState("VotingStatus");

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      setMessage(err.response?.data?.error || err.message);
    }
  };

  // ---------------- API Calls ----------------
  const fetchVotingState = async () => { try { const res = await api.get("/admin/voting-state"); setVotingOpen(res.data.votingOpen); } catch (err) { handleApiError(err); } };
  const fetchPendingUsers = async () => { try { const res = await api.get("/admin/pending-users"); setPendingUsers(res.data); } catch (err) { handleApiError(err); } };
  const fetchCandidates = async () => { try { const res = await api.get("/admin/candidates"); setCandidates(res.data); } catch (err) { handleApiError(err); } };
  const fetchLogs = async () => { try { const res = await api.get("/admin/logs"); setLogs(res.data); } catch (err) { handleApiError(err); } };
  const fetchElections = async () => {
    try {
      const res = await api.get("/admin/elections");
      const sorted = res.data.sort((a, b) => new Date(b.startsAt) - new Date(a.startsAt));
      setElections(sorted);
      if (sorted.length > 0) {
        const firstElection = sorted[0];
        setSelectedElection(firstElection.id);
        setSelectedElectionVotingOpen(firstElection.votingOpen);
        fetchResults(firstElection.id);
      }
    } catch (err) { handleApiError(err); }
  };
  const fetchResults = async (electionId) => { try { const res = await api.get("/admin/results", { params: { electionId } }); setResults(res.data.positionResults || {}); setWinners(res.data.winners || {}); } catch (err) { handleApiError(err); } };

  const toggleVoting = async () => { try { const res = await api.post("/admin/toggle-voting"); setVotingOpen(res.data.votingOpen); setMessage(`Voting is now ${res.data.votingOpen ? "OPEN" : "CLOSED"}`); } catch (err) { handleApiError(err); } };
  const approveUser = async (id) => { try { await api.post(`/admin/approve-user/${id}`); fetchPendingUsers(); } catch (err) { handleApiError(err); } };
  const rejectUser = async (id) => { try { await api.post(`/admin/reject-user/${id}`); fetchPendingUsers(); } catch (err) { handleApiError(err); } };
  const approveCandidate = async (id) => { try { await api.post(`/admin/approve-candidate/${id}`); fetchCandidates(); } catch (err) { handleApiError(err); } };
  const deleteCandidate = async (id) => { if (!window.confirm("Delete this candidate?")) return; try { await api.delete(`/admin/candidates/${id}`); fetchCandidates(); } catch (err) { handleApiError(err); } };
  const generateReport = async () => { try { const res = await api.post("/admin/generate-report"); setReportHash(res.data.hash); } catch (err) { handleApiError(err); } };
  const handleElectionChange = (id) => { const election = elections.find((el) => el.id === id); setSelectedElection(id); setSelectedElectionVotingOpen(election?.votingOpen ?? false); fetchResults(id); };

  useEffect(() => {
    if (!token) { navigate("/login"); return; }
    const init = async () => { await fetchVotingState(); await fetchPendingUsers(); await fetchCandidates(); await fetchLogs(); await fetchElections(); };
    init();
  }, [token]);

  // ---------------- Rendered Sections ----------------
  const renderContent = () => {
    switch (activeTab) {
      case "VotingStatus":
        return (
          <Card title="Voting Status">
            <p className={`font-bold ${votingOpen ? "text-green-600" : "text-red-600"}`}>{votingOpen ? "Open" : "Closed"}</p>
            <button onClick={toggleVoting} className={`mt-3 px-4 py-2 rounded font-bold text-white ${votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700"}`}>
              {votingOpen ? "Close Voting" : "Open Voting"}
            </button>
          </Card>
        );
      case "PendingUsers":
        return (
          <Card title="Pending Voter Registrations">
            {pendingUsers.length === 0 ? <p className="text-gray-500 italic">No pending users.</p> :
              <table className="w-full border-collapse">
                <thead><tr className="bg-gray-200"><th className="p-2 text-left">Student #</th><th className="p-2 text-left">Name</th><th className="p-2 text-left">Email</th><th className="p-2 text-center">Actions</th></tr></thead>
                <tbody>{pendingUsers.map(u => <tr key={u.id} className="border-t"><td className="p-2">{u.studentNumber}</td><td className="p-2">{u.name}</td><td className="p-2">{u.email}</td><td className="p-2 text-center"><button onClick={() => approveUser(u.id)} className="mr-2 bg-green-600 hover:bg-green-700 text-white px-2 py-1 rounded">Approve</button><button onClick={() => rejectUser(u.id)} className="bg-red-600 hover:bg-red-700 text-white px-2 py-1 rounded">Reject</button></td></tr>)}</tbody>
              </table>}
          </Card>
        );
      case "Candidates":
        return (
          <Card title="Candidates">
            {candidates.length === 0 ? <p className="text-gray-500 italic">No candidates registered.</p> :
              <table className="w-full border-collapse">
                <thead><tr className="bg-gray-200"><th className="p-2 text-left">Name</th><th className="p-2 text-left">Position</th><th className="p-2 text-left">Party</th><th className="p-2 text-left">Forms</th><th className="p-2 text-center">Status</th><th className="p-2 text-center">Actions</th></tr></thead>
                <tbody>{candidates.map(c => <tr key={c.id} className={`border-t ${c.approved ? "bg-green-50" : (!c.documents || c.documents.length === 0) ? "bg-red-50" : "bg-white"}`}><td className="p-2">{c.name}</td><td className="p-2">{c.position}</td><td className="p-2">{c.party || "-"}</td><td className="p-2">{c.documents && c.documents.length > 0 ? c.documents.map((doc,index)=><div key={index}><a href={`${process.env.REACT_APP_SERVER_URL || "http://localhost:4000"}/uploads/candidate-docs/${doc}`} target="_blank" rel="noopener noreferrer" className="text-blue-600 underline">Form {index+1}</a></div>) : <span className="text-red-600 font-bold italic">No form submitted</span>}</td><td className={`p-2 text-center font-bold ${c.approved ? "text-green-600" : "text-orange-600"}`}>{c.approved ? "Approved" : "Pending"}</td><td className="p-2 text-center"><button onClick={() => approveCandidate(c.id)} disabled={c.approved || !c.documents || c.documents.length===0} className={`mr-2 px-2 py-1 rounded text-white ${c.approved || !c.documents || c.documents.length===0 ? "bg-gray-400 cursor-not-allowed" : "bg-green-600 hover:bg-green-700"}`}>{c.approved ? "Approved" : (!c.documents || c.documents.length===0 ? "No Form" : "Approve")}</button><button onClick={()=>deleteCandidate(c.id)} className="px-2 py-1 rounded bg-red-600 hover:bg-red-700 text-white">Delete</button></td></tr>)}</tbody>
              </table>}
          </Card>
        );
      case "Results":
        return (
          <Card title="Election Results">
            {elections.length>0 && <div className="mb-3 flex items-center"><label htmlFor="electionSelect" className="font-bold mr-2">Select Election:</label><select id="electionSelect" value={selectedElection || ""} onChange={e=>handleElectionChange(parseInt(e.target.value))} className="p-1 rounded">{elections.map(el=>{const start=el.startsAt?new Date(el.startsAt).toLocaleString():"N/A"; const end=el.votingOpen?"Ongoing":el.endsAt?new Date(el.endsAt).toLocaleString():"Closed"; return <option key={el.id} value={el.id}>{el.name} ({start} - {end})</option>})}</select></div>}
            {Object.keys(results).length===0?<p className="text-gray-500 italic">No results yet.</p>:Object.keys(results).map(pos=><div key={pos} className="mb-5"><h3 className="mb-2">{pos}</h3><table className="w-full border-collapse"><thead><tr className="bg-gray-200"><th className="p-2 text-left">Name</th><th className="p-2 text-left">Party</th><th className="p-2 text-center">Votes</th><th className="p-2 text-center">Status</th></tr></thead><tbody>{results[pos].map(c=><tr key={c.id} className="border-t"><td className="p-2">{c.name}</td><td className="p-2">{c.party||"-"}</td><td className="p-2 text-center">{c.votes}</td><td className="p-2 text-center font-bold">{!selectedElectionVotingOpen && winners[pos]?.id===c.id?<span className="text-green-600">Winner</span>:"—"}</td></tr>)}</tbody></table></div>)}
          </Card>
        );
      case "Reports":
        return (
          <Card title="Reports">
            <button onClick={generateReport} className="px-4 py-2 rounded bg-blue-600 hover:bg-blue-700 text-white font-bold">Generate Final Report</button>
            {reportHash && <p className="mt-2 text-gray-600 text-sm">Cryptographic Hash: <span className="font-mono">{reportHash}</span></p>}
          </Card>
        );
      default: return null;
    }
  };

  return (
    <div className="flex min-h-screen bg-gray-100 font-sans">
      {/* Sidebar */}
      <aside className={`flex flex-col bg-gray-800 text-white transition-all duration-300 ${sidebarOpen ? "w-56" : "w-16"}`}>
        <div className="flex items-center justify-between p-3">
          {sidebarOpen && <span className="text-lg font-bold">iVote Admin</span>}
          <button onClick={()=>setSidebarOpen(!sidebarOpen)} className="text-2xl">{sidebarOpen ? "←" : "☰"}</button>
        </div>
        <nav className="flex flex-col flex-1 mt-5 space-y-2 px-2">
          <button className={`flex items-center space-x-2 w-full text-left p-2 rounded hover:bg-gray-700 ${activeTab==="VotingStatus"?"font-bold bg-gray-700":""}`} onClick={()=>setActiveTab("VotingStatus")}>🏠 {sidebarOpen && "Voting Status"}</button>
          <button className={`flex items-center space-x-2 w-full text-left p-2 rounded hover:bg-gray-700 ${activeTab==="PendingUsers"?"font-bold bg-gray-700":""}`} onClick={()=>setActiveTab("PendingUsers")}>🧑 {sidebarOpen && "Pending Users"}</button>
          <button className={`flex items-center space-x-2 w-full text-left p-2 rounded hover:bg-gray-700 ${activeTab==="Candidates"?"font-bold bg-gray-700":""}`} onClick={()=>setActiveTab("Candidates")}>👤 {sidebarOpen && "Candidates"}</button>
          <button className={`flex items-center space-x-2 w-full text-left p-2 rounded hover:bg-gray-700 ${activeTab==="Results"?"font-bold bg-gray-700":""}`} onClick={()=>setActiveTab("Results")}>📊 {sidebarOpen && "Results"}</button>
          <button className={`flex items-center space-x-2 w-full text-left p-2 rounded hover:bg-gray-700 ${activeTab==="Reports"?"font-bold bg-gray-700":""}`} onClick={()=>setActiveTab("Reports")}>📄 {sidebarOpen && "Reports"}</button>
        </nav>
        <button onClick={()=>{logout();navigate("/login")}} className="m-3 mt-auto p-2 bg-red-600 hover:bg-red-700 rounded font-bold flex items-center justify-center">{sidebarOpen ? "Logout" : "⏻"}</button>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-8 max-w-6xl mx-auto">
        {renderContent()}
        {message && <p className={`text-center mt-5 font-bold ${message.toLowerCase().includes("fail")?"text-red-600":"text-green-600"}`}>{message}</p>}
      </main>
    </div>
  );
}
